# message type in langchain    : 1 system message, 2 human message, 3 ai message
# system message: provide instructions, guidelines, or context to the model. It sets the tone and direction for the conversation.
# human message: represents the input or query from the user. It is the message that the user sends to the model, asking for information, clarification, or assistance.
# ai message: represents the response generated by the model. It is the message that the model
# sends back to the user after processing the human message. The AI message contains the information, answer, or assistance provided by the model based on the user's input and the instructions given in the system message.


from langchain_core.messages import SystemMessage, HumanMessage, AIMessage
from langchain_openai import ChatOpenAI
from dotenv import load_dotenv

load_dotenv()
model = ChatOpenAI()

messages = [
    SystemMessage(content="You are a helpful assistant that provides information about the latest research papers in AI."),
    HumanMessage(content="What are some of the most influential research papers in AI?"),
    # AIMessage(content="Some of the most influential research papers in AI include 'Attention Is All You Need', 'GPT-3: Language Models are Few-Shot Learners', and 'Diffusion Models Beat GANs on Image Synthesis'.")
]


result = model.invoke(messages)

messages.append(AIMessage(content=result.content))

# print("Response:")
# print("AI: " ,result.content)

print("\nChat History:")
for message in messages:
    print(f"{message.__class__.__name__}: {message.content}")
